// ELEMENTS (mockup, top to bottom):
// 1. Thin accent bar across the very top edge
// 2. Full-bleed property photo (placeholder when missing)
// 3. Short accent strip on the left, sitting on the panel's top edge
// 4. White price box straddling the panel's top edge, right-aligned ("385.000 €")
// 5. Solid colour panel covering the bottom ~41%
// 6. Eyebrow "NOVO IMÓVEL" (small, uppercase, wide letter-spacing)
// 7. Headline "Moradia T4 com jardim" (bold, large, up to 2 lines)
// 8. Location row: pin icon + "Viseu · 240 m² · 4 quartos"
// 9. Agent avatar circle (portrait image or placeholder "retrato")
// 10. Agent name (bold) + phone
// 11. Logo box, bottom right (logo image or placeholder "logótipo")
// 12. Footer small print "Agência Imobiliária, Lda. | AMI: 00000"
import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring, Easing, Img } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const GREEN = "#1B6B4E";
const GREEN_DARK = "#0E3F2E";
const GREEN_MID = "#145A41";
const WHITE = "#FFFFFF";
const PLACEHOLDER = "#E1E5EF";

const str = (v: unknown): string => (v === undefined || v === null ? "" : String(v));

const AnuncioImovelDesfoque: React.FC<PrimitiveProps> = ({ anim, fps, format, frame }) => {
  const f = useCurrentFrame();
  const W = frame.width;
  const H = frame.height;
  const D = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const p = anim.params ?? {};

  const src = str(p.src);
  const avatar = str(p.avatar);
  const logo = str(p.logo);
  const eyebrow = str(p.eyebrow);
  const title = str(p.title) || str(anim.text);
  const location = str(p.location);
  const price = str(p.price);
  const agentName = str(p.agentName);
  const agentPhone = str(p.agentPhone);
  const footer = str(p.footer);

  const landscape = format === "landscape";
  // scale unit: mockup was drawn 438px wide
  const s = format === "portrait" ? W / 438 : format === "half" ? Math.min(W / 438, H / 520) : Math.min(W / 760, H / 560);

  // --- timing (everything settled by 0.6 * D) ---
  const dur = Math.max(1, Math.round(0.08 * D));
  const sp = (at: number, bouncy = false) =>
    spring({
      frame: f - Math.round(at * D),
      fps,
      durationInFrames: dur,
      config: bouncy ? { damping: 9, stiffness: 160, mass: 0.8 } : { damping: 200 },
    });
  const unblurEnd = Math.max(1, Math.round(0.15 * D));
  const blur = interpolate(f, [0, unblurEnd], [14 * s, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const photoScale = interpolate(f, [0, unblurEnd], [1.08, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  const topBar = sp(0.12);
  const panel = sp(0.16);
  const strip = sp(0.26);
  const priceP = sp(0.3, true);
  const eyebrowP = sp(0.3);
  const titleP = sp(0.35);
  const locP = sp(0.4);
  const avatarP = sp(0.44, true);
  const agentP = sp(0.46);
  const logoP = sp(0.48, true);
  const footerP = sp(0.52);

  const rise = (v: number, dist = 24): React.CSSProperties => ({
    opacity: Math.min(1, Math.max(0, v)),
    transform: `translateY(${(1 - v) * dist * s}px)`,
  });

  const titleLen = title.length;
  const titleSize = 42 * s * (titleLen > 48 ? 0.66 : titleLen > 30 ? 0.8 : 1);

  const pad = 20 * s;

  const placeholderText: React.CSSProperties = {
    fontFamily: FONTS.body,
    color: "rgba(255,255,255,0.75)",
    fontSize: 6 * s,
    textAlign: "center",
    lineHeight: 1.3,
  };

  const eyebrowEl = eyebrow ? (
    <div
      style={{
        ...rise(eyebrowP),
        fontFamily: FONTS.body,
        fontWeight: 500,
        fontSize: 11 * s,
        letterSpacing: "0.2em",
        textTransform: "uppercase",
        color: "rgba(255,255,255,0.9)",
        marginBottom: 8 * s,
      }}
    >
      {eyebrow}
    </div>
  ) : null;

  const titleEl = title ? (
    <div
      style={{
        ...rise(titleP, 30),
        fontFamily: FONTS.body,
        fontWeight: 700,
        fontSize: titleSize,
        lineHeight: 1.0,
        letterSpacing: "-0.01em",
        color: WHITE,
        overflowWrap: "break-word",
        marginBottom: 12 * s,
      }}
    >
      {title}
    </div>
  ) : null;

  const locEl = location ? (
    <div
      style={{
        ...rise(locP),
        display: "flex",
        alignItems: "center",
        gap: 6 * s,
        fontFamily: FONTS.body,
        fontWeight: 500,
        fontSize: 14 * s,
        color: WHITE,
      }}
    >
      <svg width={14 * s} height={14 * s} viewBox="0 0 24 24" fill="none" stroke={WHITE} strokeWidth={2} style={{ flexShrink: 0 }}>
        <path d="M12 21s-7-6.2-7-11a7 7 0 0 1 14 0c0 4.8-7 11-7 11z" />
        <circle cx="12" cy="10" r="2.5" />
      </svg>
      <span>{location}</span>
    </div>
  ) : null;

  const avatarSize = 34 * s;
  const agentEl = (
    <div style={{ display: "flex", alignItems: "center", gap: 10 * s, minWidth: 0 }}>
      <div
        style={{
          width: avatarSize,
          height: avatarSize,
          borderRadius: "50%",
          overflow: "hidden",
          flexShrink: 0,
          background: GREEN_MID,
          border: `${Math.max(1, 1.5 * s)}px solid rgba(255,255,255,0.35)`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          opacity: Math.min(1, avatarP),
          transform: `scale(${Math.max(0, avatarP)})`,
        }}
      >
        {avatar ? (
          <Img src={avatar} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        ) : (
          <span style={placeholderText}>retrato</span>
        )}
      </div>
      {agentName || agentPhone ? (
        <div style={{ ...rise(agentP, 16), fontFamily: FONTS.body, color: WHITE, lineHeight: 1.25 }}>
          {agentName ? <div style={{ fontWeight: 700, fontSize: 12.5 * s }}>{agentName}</div> : null}
          {agentPhone ? <div style={{ fontWeight: 400, fontSize: 12 * s }}>{agentPhone}</div> : null}
        </div>
      ) : null}
    </div>
  );

  const logoEl = (
    <div
      style={{
        width: 82 * s,
        minHeight: 28 * s,
        flexShrink: 0,
        background: logo ? "transparent" : GREEN_MID,
        border: logo ? undefined : `1px solid rgba(255,255,255,0.22)`,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        opacity: Math.min(1, Math.max(0, logoP)),
        transform: `scale(${0.7 + 0.3 * logoP})`,
      }}
    >
      {logo ? (
        <Img src={logo} style={{ width: "100%", height: 28 * s, objectFit: "contain" }} />
      ) : (
        <span style={placeholderText}>logótipo</span>
      )}
    </div>
  );

  const footerEl = footer ? (
    <div
      style={{
        ...rise(footerP, 12),
        fontFamily: FONTS.body,
        fontSize: 7 * s,
        color: "rgba(255,255,255,0.75)",
        marginTop: 12 * s,
      }}
    >
      {footer}
    </div>
  ) : null;

  return (
    <AbsoluteFill>
      {/* 2. hero photo, blurred → sharp */}
      <AbsoluteFill style={{ background: src ? "transparent" : PLACEHOLDER, alignItems: "center", justifyContent: "center" }}>
        {src ? (
          <Img
            src={src}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              filter: `blur(${blur}px)`,
              transform: `scale(${photoScale})`,
            }}
          />
        ) : (
          <div
            style={{
              fontFamily: FONTS.body,
              fontSize: 9 * s,
              color: "#8A8A8A",
              marginTop: landscape ? -0.3 * H : -0.25 * H,
              filter: `blur(${blur}px)`,
            }}
          >
            Fotografia do imóvel
          </div>
        )}
      </AbsoluteFill>

      {/* 1. top accent bar */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: W,
          height: Math.max(3, 4 * s),
          background: GREEN_DARK,
          transformOrigin: "left center",
          transform: `scaleX(${topBar})`,
        }}
      />

      {/* 5. bottom panel */}
      <div
        style={{
          position: "absolute",
          left: 0,
          bottom: 0,
          width: W,
          minHeight: format === "portrait" ? 0.411 * H : undefined,
          background: GREEN,
          boxSizing: "border-box",
          padding: `${landscape ? 40 * s : 44 * s}px ${pad}px ${landscape ? 28 * s : 32 * s}px`,
          transform: `translateY(${(1 - panel) * 110}%)`,
        }}
      >
        {/* 3. accent strip on the panel edge */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: landscape ? 0.18 * W : 0.256 * W,
            height: Math.max(3, 4 * s),
            background: GREEN_DARK,
            transform: `translateY(-100%) scaleX(${strip})`,
            transformOrigin: "left center",
          }}
        />
        {/* 4. price box */}
        {price ? (
          <div
            style={{
              position: "absolute",
              right: 0.048 * W,
              top: 0,
              transform: `translateY(${-55 - (1 - priceP) * 60}%) scale(${0.6 + 0.4 * priceP})`,
              transformOrigin: "center bottom",
              opacity: Math.min(1, Math.max(0, priceP * 1.5)),
              background: WHITE,
              borderRadius: 4 * s,
              padding: `${8 * s}px ${14 * s}px`,
              fontFamily: FONTS.body,
              fontWeight: 800,
              fontSize: 31 * s,
              lineHeight: 1.15,
              letterSpacing: "-0.01em",
              color: GREEN_DARK,
              whiteSpace: "nowrap",
            }}
          >
            {price}
          </div>
        ) : null}

        {landscape ? (
          <div style={{ display: "flex", alignItems: "flex-end", gap: 40 * s }}>
            <div style={{ flex: 1, minWidth: 0 }}>
              {eyebrowEl}
              {titleEl}
              {locEl}
            </div>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 12 * s, flexShrink: 0 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 24 * s }}>
                {agentEl}
                {logoEl}
              </div>
              {footerEl}
            </div>
          </div>
        ) : (
          <div>
            {eyebrowEl}
            {titleEl}
            {locEl}
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 16 * s, marginTop: 18 * s }}>
              {agentEl}
              {logoEl}
            </div>
            {footerEl}
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default AnuncioImovelDesfoque;

