// ELEMENTS (mockup, top to bottom):
// 1. Thin red bar across the very top edge
// 2. Property photo filling the frame (covered at the bottom by the panel)
// 3. White price tag with rounded corners, navy bold "385.000 €", sitting on the photo/panel seam, right-aligned
// 4. Navy panel covering the bottom ~42% of the frame (flat top edge)
// 5. Short red bar on the panel's top edge, left side (~25% wide)
// 6. Eyebrow "NOVO IMÓVEL" — small, white, wide letter-spacing, uppercase
// 7. Headline "Moradia T4 com jardim" — large, bold, white, sentence case, wraps to 2 lines
// 8. Location pin icon + facts line "Viseu · 240 m² · 4 quartos"
// 9. Round agent avatar (portrait) with a faint ring, bottom-left
// 10. Agent name "Nome do Agente" (bold) over phone "+351 900 000 000"
// 11. Company logo box, bottom-right, aligned with the agent row
// 12. Legal line "Agência Imobiliária, Lda. | AMI: 00000" — tiny, white
import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring, Easing, Img } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#0B2A5C";
const NAVY_SOFT = "#163B72";
const RED = "#D7252D";
const WHITE = "#FFFFFF";
const PHOTO_PLACEHOLDER = "#E2E6F0";

const ImovelRevelacao: React.FC<PrimitiveProps> = ({ anim, fps, format, frame }) => {
  const f = useCurrentFrame();
  const W = frame.width;
  const H = frame.height;
  const params = anim.params ?? {};
  const txt = (k: string) => String(params[k] ?? "").trim();

  const src = String(anim.params?.src ?? "");
  const avatar = String(anim.params?.avatar ?? "");
  const logo = String(anim.params?.logo ?? "");
  const tag = txt("tag");
  const title = txt("title") || String(anim.text ?? "").trim();
  const details = txt("details");
  const price = txt("price");
  const name = txt("name");
  const phone = txt("phone");
  const legal = txt("legal");

  const land = format === "landscape";
  // u = one pixel of the 438px-wide mockup, scaled to the box we are given
  const u = format === "portrait" ? W / 438 : H / (land ? 540 : 600);
  const panelTop = H * (format === "portrait" ? 0.585 : land ? 0.56 : 0.5);
  const padX = land ? Math.max(20 * u, W * 0.045) : 20 * u;

  // timing: everything is in place by 60% of the layer
  const len = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const T = Math.max(8, len * 0.6);
  const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
  const prog = (a: number, b: number, easing = Easing.out(Easing.cubic)) =>
    interpolate(f, [a * T, b * T], [0, 1], { ...clamp, easing });
  const pop = (a: number, b: number) =>
    spring({
      frame: Math.max(0, f - a * T),
      fps,
      config: { damping: 9, stiffness: 140, mass: 0.8 },
      durationInFrames: Math.max(1, Math.round((b - a) * T)),
    });
  const rise = (p: number, d: number): React.CSSProperties => ({
    opacity: p,
    transform: `translateY(${(1 - p) * d}px)`,
  });

  const pImg = prog(0, 0.3);
  const pTopBar = prog(0.25, 0.45);
  const pPanel = prog(0.25, 0.55, Easing.out(Easing.back(1.1)));
  const pSeam = prog(0.5, 0.65);
  const vPrice = pop(0.55, 0.85);
  const pEyebrow = prog(0.5, 0.68);
  const pTitle = prog(0.55, 0.75);
  const pDetails = prog(0.62, 0.8);
  const vAvatar = pop(0.68, 0.95);
  const pName = prog(0.72, 0.9);
  const vLogo = pop(0.75, 1);
  const pLegal = prog(0.85, 1);

  const titleSize = 38 * u * Math.min(1, Math.max(0.6, Math.sqrt(40 / Math.max(1, title.length))));
  const priceSize = 30 * u * Math.min(1, 11 / Math.max(1, price.length));
  const font = FONTS.body;

  const eyebrowEl = tag ? (
    <div
      style={{
        ...rise(pEyebrow, 20 * u),
        fontFamily: font,
        fontWeight: 500,
        fontSize: 11 * u,
        letterSpacing: "0.22em",
        textTransform: "uppercase",
        color: WHITE,
        marginBottom: 8 * u,
        lineHeight: 1.2,
      }}
    >
      {tag}
    </div>
  ) : null;

  const titleEl = title ? (
    <div
      style={{
        ...rise(pTitle, 28 * u),
        fontFamily: font,
        fontWeight: 700,
        fontSize: titleSize,
        lineHeight: 1.05,
        letterSpacing: "-0.01em",
        color: WHITE,
        marginBottom: 10 * u,
        overflowWrap: "break-word",
      }}
    >
      {title}
    </div>
  ) : null;

  const detailsEl = details ? (
    <div
      style={{
        ...rise(pDetails, 20 * u),
        display: "flex",
        alignItems: "center",
        gap: 7 * u,
        fontFamily: font,
        fontWeight: 400,
        fontSize: 13 * u,
        lineHeight: 1.3,
        color: WHITE,
        marginBottom: 14 * u,
      }}
    >
      <div style={{ width: 13 * u, height: 13 * u, flexShrink: 0, position: "relative" }}>
        <div
          style={{
            position: "absolute",
            left: 1.5 * u,
            top: 0,
            width: 10 * u,
            height: 10 * u,
            border: `${1.6 * u}px solid ${WHITE}`,
            borderRadius: "50% 50% 50% 0",
            transform: "rotate(-45deg)",
            boxSizing: "border-box",
          }}
        />
        <div
          style={{
            position: "absolute",
            left: 5 * u,
            top: 3.5 * u,
            width: 3 * u,
            height: 3 * u,
            borderRadius: "50%",
            background: WHITE,
          }}
        />
      </div>
      <span>{details}</span>
    </div>
  ) : null;

  const agentEl = (
    <div style={{ display: "flex", alignItems: "center", gap: 10 * u }}>
      <div
        style={{
          width: 34 * u,
          height: 34 * u,
          borderRadius: "50%",
          overflow: "hidden",
          flexShrink: 0,
          border: `${u}px solid rgba(255,255,255,0.35)`,
          background: NAVY_SOFT,
          transform: `scale(${vAvatar})`,
          boxSizing: "border-box",
        }}
      >
        {avatar ? <Img src={avatar} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : null}
      </div>
      {name || phone ? (
        <div style={{ ...rise(pName, 16 * u), fontFamily: font, color: WHITE, lineHeight: 1.25 }}>
          {name ? <div style={{ fontWeight: 700, fontSize: 12.5 * u }}>{name}</div> : null}
          {phone ? <div style={{ fontWeight: 400, fontSize: 12 * u }}>{phone}</div> : null}
        </div>
      ) : null}
    </div>
  );

  const logoEl = (
    <div
      style={{
        opacity: Math.min(1, vLogo * 2),
        transform: `translateY(${(1 - vLogo) * -30 * u}px)`,
        flexShrink: 0,
      }}
    >
      {logo ? (
        <Img src={logo} style={{ height: 28 * u, maxWidth: 110 * u, objectFit: "contain", display: "block" }} />
      ) : (
        <div
          style={{
            width: 82 * u,
            height: 28 * u,
            border: "1px solid rgba(255,255,255,0.18)",
            background: "rgba(255,255,255,0.04)",
          }}
        />
      )}
    </div>
  );

  const legalEl = legal ? (
    <div
      style={{
        opacity: pLegal,
        fontFamily: font,
        fontWeight: 400,
        fontSize: 7.5 * u,
        lineHeight: 1.3,
        color: WHITE,
      }}
    >
      {legal}
    </div>
  ) : null;

  return (
    <AbsoluteFill>
      {/* 2. hero photo — fills the whole box first */}
      <AbsoluteFill style={{ opacity: pImg, overflow: "hidden" }}>
        {src ? (
          <Img
            src={src}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              transform: `scale(${1.12 - 0.12 * pImg})`,
            }}
          />
        ) : (
          <AbsoluteFill style={{ background: PHOTO_PLACEHOLDER }} />
        )}
      </AbsoluteFill>

      {/* 1. top red bar */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: "100%",
          height: 4 * u,
          background: RED,
          transform: `scaleX(${pTopBar})`,
          transformOrigin: "left center",
        }}
      />

      {/* 4. navy panel */}
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: panelTop,
          bottom: -60 * u,
          background: NAVY,
          transform: `translateY(${(1 - pPanel) * (H - panelTop + 60 * u)}px)`,
        }}
      >
        {/* 5. red seam bar */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: "25.6%",
            height: 4 * u,
            background: RED,
            transform: `scaleX(${pSeam})`,
            transformOrigin: "left center",
          }}
        />

        {land ? (
          <div style={{ padding: `${40 * u}px ${padX}px 0`, display: "flex", flexDirection: "column" }}>
            <div style={{ display: "flex", alignItems: "flex-start", gap: 30 * u }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                {eyebrowEl}
                {titleEl}
                {detailsEl}
              </div>
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "flex-end",
                  gap: 16 * u,
                  paddingTop: 34 * u,
                  flexShrink: 0,
                }}
              >
                {agentEl}
                {logoEl}
              </div>
            </div>
            {legalEl}
          </div>
        ) : (
          <div style={{ padding: `${43 * u}px ${padX}px 0`, display: "flex", flexDirection: "column" }}>
            {eyebrowEl}
            {titleEl}
            {detailsEl}
            <div style={{ display: "flex", alignItems: "center", gap: 12 * u, marginBottom: 14 * u }}>
              <div style={{ flex: 1, minWidth: 0 }}>{agentEl}</div>
              {logoEl}
            </div>
            {legalEl}
          </div>
        )}
      </div>

      {/* 3. price tag on the seam */}
      {price ? (
        <div
          style={{
            position: "absolute",
            right: land ? padX : W * 0.048,
            top: panelTop - 23 * u,
            background: WHITE,
            borderRadius: 6 * u,
            padding: `${9 * u}px ${15 * u}px`,
            fontFamily: font,
            fontWeight: 700,
            fontSize: priceSize,
            lineHeight: 1.1,
            color: NAVY,
            whiteSpace: "nowrap",
            opacity: Math.min(1, vPrice * 2),
            transform: `translateY(${(1 - vPrice) * -40 * u}px) scale(${0.6 + 0.4 * vPrice})`,
            transformOrigin: "center right",
          }}
        >
          {price}
        </div>
      ) : null}
    </AbsoluteFill>
  );
};

export default ImovelRevelacao;

// ELEMENTS (mockup, top to bottom):
// 1. Thin red bar across the full top edge
// 2. Full-bleed property photo (placeholder = light grey-blue fill with a small label)
// 3. Navy panel covering the lower ~42% of the frame (straight top edge)
// 4. Short red line at the panel's top-left seam
// 5. White price box with rounded corners, navy bold price, sitting on the seam at the right
// 6. Eyebrow "NOVO IMÓVEL" (light, spaced uppercase)
// 7. Headline "Moradia T4 com jardim" (white, bold, 2 lines)
// 8. Map-pin icon + facts line "Viseu · 240 m² · 4 quartos"
// 9. Round agent avatar (portrait slot) with a thin ring
// 10. Agent name (bold) + phone number under it
// 11. Logo box at the bottom right (logo slot)
// 12. Small legal line "Agência Imobiliária, Lda. | AMI: 00000"
import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring, Easing, Img } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#0B2C5E";
const RED = "#E3262F";
const WHITE = "#FFFFFF";
const EYEBROW = "#DCE3F0";
const LEGAL = "#B8C4DA";
const PHOTO_PH = "#E1E5EF";
const SLOT_FILL = "#163A70";
const SLOT_BORDER = "#3A5584";

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const ImovelRevelacaoFicha: React.FC<PrimitiveProps> = ({ anim, fps, format, frame }) => {
  const f = useCurrentFrame();
  const W = frame.width;
  const H = frame.height;
  const p = anim.params ?? {};
  const str = (key: string, fallback = ""): string => {
    const v = p[key];
    return v === undefined || v === null ? fallback : String(v);
  };

  const src = String(anim.params?.src ?? "");
  const avatar = String(anim.params?.avatar ?? "");
  const logo = String(anim.params?.logo ?? "");
  const tag = str("tag", "NOVO IMÓVEL");
  const title = str("title", anim.text ?? "");
  const price = str("price");
  const facts = str("facts");
  const name = str("name");
  const phone = str("phone");
  const legal = str("legal");

  const landscape = format === "landscape";
  const half = format === "half";
  // k = one mockup pixel (mockup is 438 wide)
  const k = landscape ? Math.min(W / 700, H / 440) : half ? Math.min(W / 438, H / 480) : Math.min(W / 438, H / 783);
  const seam = H * (landscape ? 0.56 : half ? 0.4 : 0.585);
  const padX = landscape ? W * 0.04 : W * 0.046;
  const ext = H * 0.08;

  // timing: everything settles by 60% of the layer
  const L = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const at = (q: number) => q * L;
  const springDur = Math.max(6, Math.round(L * 0.17));
  const sp = (q: number, damping: number) =>
    spring({ frame: f - at(q), fps, config: { damping, stiffness: 140, mass: 0.8 }, durationInFrames: springDur });
  const ease = (q: number, len = 0.14) =>
    interpolate(f, [at(q), at(q + len)], [0, 1], { ...clamp, easing: Easing.out(Easing.cubic) });

  const blur = interpolate(f, [0, at(0.14)], [W * 0.03, 0], { ...clamp, easing: Easing.out(Easing.quad) });
  const photoScale = interpolate(f, [0, at(0.2)], [1.12, 1], { ...clamp, easing: Easing.out(Easing.cubic) });
  const topBar = ease(0.08);
  const panelIn = sp(0.12, 20);
  const seamLine = ease(0.2);
  const pricePop = sp(0.22, 9);
  const eyebrowIn = ease(0.26);
  const titleIn = sp(0.3, 12);
  const titleFade = ease(0.3, 0.1);
  const factsIn = ease(0.36);
  const avatarPop = sp(0.38, 9);
  const nameIn = ease(0.4);
  const logoIn = sp(0.42, 12);
  const legalIn = ease(0.44);

  const baseTitle = (landscape ? 34 : 36) * k;
  const titleSize = baseTitle * Math.max(0.55, Math.min(1, Math.sqrt(22 / Math.max(1, title.length))));

  const eyebrowEl = tag ? (
    <div
      style={{
        fontFamily: FONTS.body,
        fontWeight: 500,
        fontSize: 11 * k,
        letterSpacing: "0.18em",
        textTransform: "uppercase",
        color: EYEBROW,
        opacity: eyebrowIn,
        transform: `translateY(${(1 - eyebrowIn) * -14 * k}px)`,
      }}
    >
      {tag}
    </div>
  ) : null;

  const titleEl = title ? (
    <div
      style={{
        marginTop: 8 * k,
        fontFamily: FONTS.display,
        fontWeight: 700,
        fontSize: titleSize,
        lineHeight: 1.05,
        color: WHITE,
        overflowWrap: "break-word",
        opacity: titleFade,
        transform: `translateY(${(1 - titleIn) * 34 * k}px)`,
      }}
    >
      {title}
    </div>
  ) : null;

  const factsEl = facts ? (
    <div
      style={{
        marginTop: 10 * k,
        display: "flex",
        alignItems: "center",
        gap: 7 * k,
        fontFamily: FONTS.body,
        fontWeight: 500,
        fontSize: 13 * k,
        lineHeight: 1.3,
        color: WHITE,
        opacity: factsIn,
        transform: `translateY(${(1 - factsIn) * 16 * k}px)`,
      }}
    >
      <div style={{ position: "relative", width: 12 * k, height: 14 * k, flexShrink: 0 }}>
        <div
          style={{
            position: "absolute",
            left: 1 * k,
            top: 0,
            width: 10 * k,
            height: 10 * k,
            border: `${1.6 * k}px solid ${WHITE}`,
            borderRadius: "50% 50% 50% 0",
            transform: "rotate(-45deg)",
            boxSizing: "border-box",
          }}
        />
        <div
          style={{
            position: "absolute",
            left: 4.5 * k,
            top: 3.5 * k,
            width: 3 * k,
            height: 3 * k,
            borderRadius: "50%",
            background: WHITE,
          }}
        />
      </div>
      <span>{facts}</span>
    </div>
  ) : null;

  const avatarSize = 34 * k;
  const footerEl = (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 16 * k }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10 * k, minWidth: 0 }}>
        <div
          style={{
            width: avatarSize,
            height: avatarSize,
            flexShrink: 0,
            borderRadius: "50%",
            border: `${1 * k}px solid ${SLOT_BORDER}`,
            background: SLOT_FILL,
            overflow: "hidden",
            transform: `scale(${avatarPop})`,
          }}
        >
          {avatar ? (
            <Img src={avatar} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          ) : null}
        </div>
        <div
          style={{
            fontFamily: FONTS.body,
            color: WHITE,
            opacity: nameIn,
            transform: `translateX(${(1 - nameIn) * -18 * k}px)`,
          }}
        >
          {name ? <div style={{ fontWeight: 700, fontSize: 12.5 * k, lineHeight: 1.25 }}>{name}</div> : null}
          {phone ? <div style={{ fontWeight: 400, fontSize: 12 * k, lineHeight: 1.3 }}>{phone}</div> : null}
        </div>
      </div>
      <div
        style={{
          width: 84 * k,
          height: 28 * k,
          flexShrink: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          background: logo ? "transparent" : SLOT_FILL,
          border: logo ? undefined : `${1 * k}px solid ${SLOT_BORDER}`,
          boxSizing: "border-box",
          opacity: Math.min(1, logoIn * 1.5),
          transform: `translateX(${(1 - logoIn) * 60 * k}px)`,
        }}
      >
        {logo ? <Img src={logo} style={{ width: "100%", height: "100%", objectFit: "contain" }} /> : null}
      </div>
    </div>
  );

  const legalEl = legal ? (
    <div
      style={{
        marginTop: 14 * k,
        fontFamily: FONTS.body,
        fontWeight: 400,
        fontSize: 7.5 * k,
        lineHeight: 1.3,
        color: LEGAL,
        opacity: legalIn,
      }}
    >
      {legal}
    </div>
  ) : null;

  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      {/* 2. photo: blurred, then snaps into focus */}
      <AbsoluteFill style={{ background: src ? "transparent" : PHOTO_PH }}>
        {src ? (
          <Img
            src={src}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              filter: `blur(${blur}px)`,
              transform: `scale(${photoScale})`,
            }}
          />
        ) : (
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: 0,
              height: seam,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontFamily: FONTS.body,
              fontSize: 8 * k,
              color: "#AEB6C8",
              filter: `blur(${blur * 0.3}px)`,
            }}
          >
            Fotografia do imóvel
          </div>
        )}
      </AbsoluteFill>

      {/* 1. top red bar */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: `${topBar * 100}%`,
          height: 4 * k,
          background: RED,
        }}
      />

      {/* 3. navy panel (grows upward if content is long) */}
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          bottom: -ext,
          minHeight: H - seam + ext,
          background: NAVY,
          boxSizing: "border-box",
          padding: `${(landscape ? 40 : 46) * k}px ${padX}px ${ext + 18 * k}px`,
          transform: `translateY(${(1 - panelIn) * 110}%)`,
        }}
      >
        {/* 4. red seam line */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: W * 0.256,
            height: 4 * k,
            background: RED,
            transform: `scaleX(${seamLine})`,
            transformOrigin: "left center",
          }}
        />

        {/* 5. price box on the seam */}
        {price ? (
          <div
            style={{
              position: "absolute",
              right: W * 0.048,
              top: -23 * k,
              background: WHITE,
              borderRadius: 6 * k,
              padding: `${8 * k}px ${14 * k}px`,
              fontFamily: FONTS.display,
              fontWeight: 800,
              fontSize: 31 * k,
              lineHeight: 1.1,
              color: NAVY,
              whiteSpace: "nowrap",
              transform: `scale(${pricePop})`,
              transformOrigin: "right center",
            }}
          >
            {price}
          </div>
        ) : null}

        {landscape ? (
          <div style={{ display: "flex", alignItems: "flex-end", gap: 40 * k }}>
            <div style={{ flex: 1.5, minWidth: 0 }}>
              {eyebrowEl}
              {titleEl}
              {factsEl}
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              {footerEl}
              {legalEl}
            </div>
          </div>
        ) : (
          <div>
            {eyebrowEl}
            {titleEl}
            {factsEl}
            <div style={{ marginTop: (half ? 12 : 16) * k }}>{footerEl}</div>
            {legalEl}
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default ImovelRevelacaoFicha;

// ELEMENTS (mockup, top to bottom):
// 1. Red stripe across the very top of the frame (#DE212B).
// 2. Property photo filling the whole frame (blurred placeholder #E2E7F2 when missing).
// 3. Navy panel (#002B5C) covering the lower ~42% of the frame.
// 4. Short red seam bar at the left end of the photo/panel seam.
// 5. White rounded price tag straddling the seam on the right, navy bold price.
// 6. Eyebrow 'NOVO IMÓVEL' - light, uppercase, wide tracking.
// 7. Headline 'Moradia T4 com jardim' - white, extra-bold, 2 lines.
// 8. Location row - outline pin icon + 'Viseu · 240 m² · 4 quartos'.
// 9. Agent avatar - circle (placeholder 'retrato').
// 10. Agent name (bold) with phone underneath.
// 11. Company logo box on the right of the agent row (placeholder 'logótipo').
// 12. Legal line 'Agência Imobiliária, Lda. | AMI: 00000'.
import React from 'react';
import { AbsoluteFill, useCurrentFrame, interpolate, spring, Easing, Img } from 'remotion';
import { FONTS } from '../style-tokens';
import type { PrimitiveProps } from '../primitives';

const RED = '#DE212B';
const NAVY = '#002B5C';
const MIST = '#C9D3E3';
const WHITE = '#FFFFFF';
const PHOTO_PH = '#E2E7F2';

const txt = (v: unknown, fallback: string): string => {
  const s = v == null ? '' : String(v).trim();
  return s || fallback;
};

const PinIcon: React.FC<{ size: number; color: string }> = ({ size, color }) => (
  <svg width={size} height={size} viewBox='0 0 24 24' fill='none' stroke={color} strokeWidth={2} strokeLinecap='round' strokeLinejoin='round' style={{ flexShrink: 0 }}>
    <path d='M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z' />
    <circle cx='12' cy='10' r='3' />
  </svg>
);

const ImovelRevelacao: React.FC<PrimitiveProps> = ({ anim, fps, format, frame }) => {
  const f = useCurrentFrame();
  const p = anim.params ?? {};
  const W = frame.width;
  const H = frame.height;
  const L = Math.max(1, Math.round((anim.end - anim.start) * fps));

  // Portrait: navy panel under the photo. Half/landscape: navy panel on the right.
  const side = format !== 'portrait';
  const pw = side ? W * (format === 'landscape' ? 0.4 : 0.5) : W;
  const u = side ? Math.min(pw / 400, H / 360) : Math.min(W / 438, H / 783);
  const panelTop = side ? 0 : H * 0.585;

  const src = String(p.src ?? '');
  const avatar = String(p.avatar ?? '');
  const logo = String(p.logo ?? '');
  const price = txt(p.price, '385.000 €');
  const eyebrow = txt(p.eyebrow, 'Novo imóvel');
  const title = txt(p.title ?? anim.text, 'Moradia T4 com jardim');
  const location = txt(p.location, 'Viseu · 240 m² · 4 quartos');
  const agentName = txt(p.agentName, 'Nome do Agente');
  const phone = txt(p.phone, '+351 900 000 000');
  const legal = txt(p.legal, 'Agência Imobiliária, Lda. | AMI: 00000');

  const at = (t: number) => t * L;
  const clamp = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;
  const pop = (t: number) =>
    spring({
      frame: f - at(t),
      fps,
      config: { damping: 10, stiffness: 160, mass: 0.7 },
      durationInFrames: Math.max(4, Math.round(L * 0.1)),
    });
  // Element rises (dir 1) or drops (dir -1) into place with a little overshoot.
  const enter = (t: number, dir = 1): React.CSSProperties => {
    const s = pop(t);
    return { opacity: Math.min(1, s * 2), transform: `translateY(${(1 - s) * 34 * u * dir}px)` };
  };

  // 1) Photo unblurs fast. 2) Stripe + panel arrive. 3) Content staggers in. All settled by 60%.
  const blur = interpolate(f, [0, at(0.18)], [26 * u, 0], { ...clamp, easing: Easing.out(Easing.cubic) });
  const zoom = interpolate(f, [0, at(0.18)], [1.08, 1], { ...clamp, easing: Easing.out(Easing.cubic) });
  const stripe = interpolate(f, [at(0.14), at(0.26)], [0, 1], { ...clamp, easing: Easing.out(Easing.cubic) });
  const panel = interpolate(f, [at(0.18), at(0.32)], [100, 0], { ...clamp, easing: Easing.out(Easing.cubic) });
  const seam = interpolate(f, [at(0.3), at(0.4)], [0, 1], { ...clamp, easing: Easing.out(Easing.cubic) });
  const tag = pop(0.3);

  const titleSize = 40 * u * (title.length <= 22 ? 1 : Math.max(0.55, Math.sqrt(22 / title.length)));
  const photoRight = side ? pw : 0;
  const photoBottom = side ? 0 : H - panelTop;

  return (
    <AbsoluteFill style={{ overflow: 'hidden' }}>
      {/* 2. Photo - full frame, blurred -> sharp */}
      <AbsoluteFill style={{ filter: `blur(${blur}px)`, transform: `scale(${zoom})` }}>
        {src ? (
          <Img src={src} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
        ) : (
          <AbsoluteFill style={{ backgroundColor: PHOTO_PH }}>
            <div
              style={{
                position: 'absolute',
                left: 0,
                top: 0,
                right: photoRight,
                bottom: photoBottom,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontFamily: FONTS.body,
                fontSize: 10 * u,
                color: '#9AA6BC',
              }}
            >
              Fotografia do imóvel
            </div>
          </AbsoluteFill>
        )}
      </AbsoluteFill>

      {/* 3. Navy panel */}
      <div
        style={{
          position: 'absolute',
          backgroundColor: NAVY,
          ...(side
            ? { top: 0, right: 0, bottom: 0, width: pw, transform: `translateX(${panel}%)` }
            : { left: 0, right: 0, top: panelTop, bottom: 0, transform: `translateY(${panel}%)` }),
        }}
      />

      {/* 4. Red seam bar */}
      <div
        style={{
          position: 'absolute',
          backgroundColor: RED,
          ...(side
            ? { left: W - pw, top: 0, width: 4.5 * u, height: 112 * u, transformOrigin: 'top', transform: `scaleY(${seam})` }
            : { left: 0, top: panelTop, width: 112 * u, height: 4.5 * u, transformOrigin: 'left', transform: `scaleX(${seam})` }),
        }}
      />

      {/* 6-12. Panel content */}
      <div
        style={{
          position: 'absolute',
          display: 'flex',
          flexDirection: 'column',
          boxSizing: 'border-box',
          ...(side
            ? { top: 0, right: 0, bottom: 0, width: pw, padding: `${24 * u}px ${24 * u}px`, justifyContent: 'center' }
            : { left: 0, right: 0, top: panelTop, bottom: 0, padding: `${44 * u}px ${20 * u}px ${20 * u}px` }),
        }}
      >
        <div
          style={{
            ...enter(0.33),
            fontFamily: FONTS.body,
            fontWeight: 600,
            fontSize: 11.5 * u,
            letterSpacing: '0.2em',
            textTransform: 'uppercase',
            color: MIST,
            marginBottom: 10 * u,
          }}
        >
          {eyebrow}
        </div>
        <div
          style={{
            ...enter(0.36),
            fontFamily: FONTS.display,
            fontWeight: 800,
            fontSize: titleSize,
            lineHeight: 1.02,
            letterSpacing: '-0.01em',
            color: WHITE,
            overflowWrap: 'break-word',
            marginBottom: 12 * u,
          }}
        >
          {title}
        </div>
        <div
          style={{
            ...enter(0.41),
            display: 'flex',
            alignItems: 'center',
            gap: 7 * u,
            fontFamily: FONTS.body,
            fontWeight: 500,
            fontSize: 15 * u,
            lineHeight: 1.2,
            color: WHITE,
            marginBottom: 20 * u,
          }}
        >
          <PinIcon size={16 * u} color={WHITE} />
          <span>{location}</span>
        </div>
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: 12 * u,
            marginBottom: 18 * u,
          }}
        >
          <div style={{ ...enter(0.45), display: 'flex', alignItems: 'center', gap: 11 * u, minWidth: 0 }}>
            {avatar ? (
              <Img src={avatar} style={{ width: 44 * u, height: 44 * u, borderRadius: '50%', objectFit: 'cover', flexShrink: 0 }} />
            ) : (
              <div
                style={{
                  width: 44 * u,
                  height: 44 * u,
                  borderRadius: '50%',
                  flexShrink: 0,
                  backgroundColor: '#1D4473',
                  border: `${u}px solid #3A5C88`,
                  boxSizing: 'border-box',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontFamily: FONTS.body,
                  fontSize: 8 * u,
                  color: MIST,
                }}
              >
                retrato
              </div>
            )}
            <div style={{ display: 'flex', flexDirection: 'column', gap: 2 * u, minWidth: 0 }}>
              <div style={{ fontFamily: FONTS.body, fontWeight: 700, fontSize: 16 * u, lineHeight: 1.2, color: WHITE }}>{agentName}</div>
              <div style={{ fontFamily: FONTS.body, fontWeight: 500, fontSize: 15 * u, lineHeight: 1.2, color: WHITE }}>{phone}</div>
            </div>
          </div>
          <div style={{ ...enter(0.48), flexShrink: 0 }}>
            {logo ? (
              <Img src={logo} style={{ height: 40 * u, maxWidth: 130 * u, objectFit: 'contain', display: 'block' }} />
            ) : (
              <div
                style={{
                  width: 104 * u,
                  height: 36 * u,
                  backgroundColor: '#0E3566',
                  border: `${u}px solid #2D4C77`,
                  boxSizing: 'border-box',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontFamily: FONTS.body,
                  fontSize: 8 * u,
                  color: '#8FA3C4',
                }}
              >
                logótipo
              </div>
            )}
          </div>
        </div>
        <div style={{ ...enter(0.5), fontFamily: FONTS.body, fontWeight: 500, fontSize: 8.5 * u, lineHeight: 1.3, color: MIST }}>
          {legal}
        </div>
      </div>

      {/* 5. Price tag - drops onto the seam */}
      <div
        style={{
          position: 'absolute',
          ...(side ? { right: pw - 12 * u, bottom: 32 * u } : { right: 21 * u, top: panelTop - 24 * u }),
          minHeight: 52 * u,
          padding: `${6 * u}px ${15 * u}px`,
          boxSizing: 'border-box',
          display: 'flex',
          alignItems: 'center',
          backgroundColor: WHITE,
          borderRadius: 7 * u,
          fontFamily: FONTS.display,
          fontWeight: 800,
          fontSize: 32 * u,
          lineHeight: 1,
          color: NAVY,
          whiteSpace: 'nowrap',
          opacity: Math.min(1, tag * 2),
          transform: `translateY(${(1 - tag) * -40 * u}px) scale(${0.85 + 0.15 * tag})`,
        }}
      >
        {price}
      </div>

      {/* 1. Red stripe - always on top */}
      <div
        style={{
          position: 'absolute',
          left: 0,
          top: 0,
          width: '100%',
          height: 5.5 * u,
          backgroundColor: RED,
          transformOrigin: 'left',
          transform: `scaleX(${stripe})`,
        }}
      />
    </AbsoluteFill>
  );
};

export default ImovelRevelacao;

// ELEMENTS (top → bottom of the mockup):
// 1. Thin red bar across the very top edge.
// 2. Full-bleed property photo (placeholder: light grey-blue box with image icon).
// 3. Navy info panel covering the lower ~41% of the frame.
// 4. Short red bar on the panel's top-left edge.
// 5. White rounded price box straddling the panel's top edge, right-aligned ("385.000 €", bold navy).
// 6. Eyebrow "NOVO IMÓVEL" — small, uppercase, wide letter-spacing, white.
// 7. Headline "Moradia T4 com jardim" — large bold white, left-aligned, wraps to 2 lines.
// 8. Location row: pin outline icon + "Viseu · 240 m² · 4 quartos".
// 9. Circular agent portrait (placeholder "retrato").
// 10. Agent name "Nome do Agente" (bold) + phone "+351 900 000 000".
// 11. Company logo box, right of the agent row (placeholder "logótipo").
// 12. Footer small print "Agência Imobiliária, Lda. | AMI: 00000".
import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring, Easing, Img } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#0A2B5C";
const RED = "#E1252F";
const WHITE = "#FFFFFF";
const PH_BG = "#E1E6F0";
const PH_INK = "#9AA6BF";
const SLOT_BG = "#12386B";
const LINE = "#3B5C8C";
const MUTED = "#C9D3E6";

const str = (v: unknown): string =>
  typeof v === "string" ? v.trim() : typeof v === "number" ? String(v) : "";

const Pin: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={WHITE} strokeWidth={2}
    strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0 }}>
    <path d="M12 21s-7-6.2-7-11.5a7 7 0 0 1 14 0C19 14.8 12 21 12 21z" />
    <circle cx="12" cy="9.5" r="2.5" />
  </svg>
);

const ImovelFichaRevelacao: React.FC<PrimitiveProps> = ({ anim, fps, format, frame }) => {
  const f = useCurrentFrame();
  const W = frame.width;
  const H = frame.height;
  const L = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const p = anim.params ?? {};

  const src = String(p.src ?? "");
  const avatar = String(p.avatar ?? "");
  const logo = String(p.logo ?? "");
  const title = str(anim.text) || str(p.title);
  const eyebrow = str(p.eyebrow);
  const price = str(p.price);
  const details = str(p.details);
  const agentName = str(p.agentName);
  const agentPhone = str(p.agentPhone);
  const footer = str(p.footer);

  const portrait = format === "portrait";
  const u =
    format === "portrait" ? Math.min(W / 100, H / 178)
    : format === "half" ? Math.min(W / 144, H / 128)
    : Math.min(W / 192, H / 100);
  const panelMin = H * (portrait ? 0.415 : format === "half" ? 0.55 : 0.45);

  // Timing — every element settles by 60% of the layer.
  const at = (x: number) => Math.round(x * L);
  const rng = (a: number, b: number): [number, number] => [at(a), Math.max(at(a) + 1, at(b))];
  const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
  const sp = (start: number, dur: number, damping = 14) =>
    spring({
      frame: f - at(start),
      fps,
      config: { damping, stiffness: 140, mass: 0.7 },
      durationInFrames: Math.max(1, at(dur)),
    });
  const rise = (s: number, dist: number): React.CSSProperties => ({
    opacity: Math.min(1, Math.max(0, s * 1.4)),
    transform: `translateY(${(1 - s) * dist}px)`,
  });

  const blur = interpolate(f, rng(0, 0.16), [0.035 * W, 0], { ...clamp, easing: Easing.out(Easing.cubic) });
  const zoom = interpolate(f, rng(0, 0.3), [1.08, 1], { ...clamp, easing: Easing.out(Easing.cubic) });
  const topBar = interpolate(f, rng(0.1, 0.22), [0, 1], { ...clamp, easing: Easing.out(Easing.cubic) });
  const panelY = interpolate(f, rng(0.12, 0.3), [100, 0], { ...clamp, easing: Easing.out(Easing.cubic) });
  const redBar = interpolate(f, rng(0.26, 0.36), [0, 1], { ...clamp, easing: Easing.out(Easing.cubic) });
  const sPrice = sp(0.28, 0.16, 9);
  const sEyebrow = sp(0.3, 0.12);
  const sTitle = sp(0.33, 0.14, 12);
  const sDetails = sp(0.37, 0.12);
  const sAvatar = sp(0.41, 0.14, 10);
  const sAgent = sp(0.43, 0.12);
  const sLogo = sp(0.45, 0.12, 11);
  const footerO = interpolate(f, rng(0.48, 0.58), [0, 1], clamp);

  // Long text shrinks instead of being cut.
  const titleSize = 9 * u * (title.length > 22 ? Math.max(0.55, Math.sqrt(22 / title.length)) : 1);
  const priceSize = 7.3 * u * (price.length > 9 ? Math.max(0.6, Math.sqrt(9 / price.length)) : 1);

  const textBlock = (
    <>
      {eyebrow ? (
        <div style={{ ...rise(sEyebrow, 3 * u), fontFamily: FONTS.body, fontWeight: 500, fontSize: 2.6 * u,
          letterSpacing: "0.22em", textTransform: "uppercase", color: WHITE }}>
          {eyebrow}
        </div>
      ) : null}
      {title ? (
        <div style={{ ...rise(sTitle, 5 * u), marginTop: 1.4 * u, fontFamily: FONTS.display, fontWeight: 700,
          fontSize: titleSize, lineHeight: 1.05, letterSpacing: "-0.01em", color: WHITE, overflowWrap: "break-word" }}>
          {title}
        </div>
      ) : null}
      {details ? (
        <div style={{ ...rise(sDetails, 3 * u), marginTop: 2 * u, display: "flex", alignItems: "center", gap: 1.2 * u,
          fontFamily: FONTS.body, fontWeight: 400, fontSize: 3.3 * u, color: WHITE, lineHeight: 1.25 }}>
          <Pin size={3.4 * u} />
          <span>{details}</span>
        </div>
      ) : null}
    </>
  );

  const avatarSize = 11 * u;
  const agentBlock = (
    <div style={{ display: "flex", alignItems: "center", gap: 2.2 * u }}>
      <div style={{ width: avatarSize, height: avatarSize, flexShrink: 0, borderRadius: "50%", overflow: "hidden",
        border: `${0.25 * u}px solid ${LINE}`, background: SLOT_BG, display: "flex", alignItems: "center",
        justifyContent: "center", opacity: Math.min(1, Math.max(0, sAvatar * 1.5)), transform: `scale(${Math.max(0, sAvatar)})` }}>
        {avatar ? (
          <Img src={avatar} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        ) : (
          <span style={{ fontFamily: FONTS.body, fontSize: 2 * u, color: MUTED }}>retrato</span>
        )}
      </div>
      {agentName || agentPhone ? (
        <div style={{ ...rise(sAgent, 3 * u), display: "flex", flexDirection: "column", gap: 0.4 * u, minWidth: 0 }}>
          {agentName ? (
            <div style={{ fontFamily: FONTS.body, fontWeight: 700, fontSize: 3.7 * u, color: WHITE, lineHeight: 1.2 }}>
              {agentName}
            </div>
          ) : null}
          {agentPhone ? (
            <div style={{ fontFamily: FONTS.body, fontWeight: 400, fontSize: 3.3 * u, color: WHITE, lineHeight: 1.2,
              whiteSpace: "nowrap" }}>
              {agentPhone}
            </div>
          ) : null}
        </div>
      ) : null}
    </div>
  );

  const logoBlock = (
    <div style={{ width: 24 * u, height: 8.5 * u, flexShrink: 0, display: "flex",
      alignItems: "center", justifyContent: "center",
      background: logo ? "transparent" : SLOT_BG, border: logo ? "none" : `${0.15 * u}px solid ${LINE}`,
      opacity: Math.min(1, Math.max(0, sLogo * 1.4)), transform: `translateY(${(1 - sLogo) * -3 * u}px)` }}>
      {logo ? (
        <Img src={logo} style={{ width: "100%", height: "100%", objectFit: "contain" }} />
      ) : (
        <span style={{ fontFamily: FONTS.body, fontSize: 2 * u, color: MUTED }}>logótipo</span>
      )}
    </div>
  );

  const footerBlock = footer ? (
    <div style={{ opacity: footerO, marginTop: 3 * u, fontFamily: FONTS.body, fontWeight: 400, fontSize: 2 * u,
      color: MUTED, lineHeight: 1.3 }}>
      {footer}
    </div>
  ) : null;

  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      {/* 2. Full-bleed photo, starts blurred and sharpens */}
      <AbsoluteFill style={{ filter: `blur(${blur}px)`, transform: `scale(${zoom})` }}>
        {src ? (
          <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        ) : (
          <AbsoluteFill style={{ background: PH_BG, alignItems: "center", justifyContent: "center",
            paddingBottom: panelMin }}>
            <svg width={6 * u} height={6 * u} viewBox="0 0 24 24" fill="none" stroke={PH_INK} strokeWidth={1.5}>
              <rect x="3" y="4" width="18" height="16" rx="1" />
              <circle cx="9" cy="10" r="2" />
              <path d="M21 17l-5-5-9 8" />
            </svg>
            <div style={{ marginTop: u, fontFamily: FONTS.body, fontSize: 2.4 * u, color: PH_INK }}>imagem do imóvel</div>
          </AbsoluteFill>
        )}
      </AbsoluteFill>

      {/* 1. Top red bar */}
      <div style={{ position: "absolute", top: 0, left: 0, width: "100%", height: 0.9 * u, background: RED,
        transformOrigin: "left center", transform: `scaleX(${topBar})` }} />

      {/* 3. Navy panel — anchored to the bottom, grows upward with its content */}
      <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, minHeight: panelMin, background: NAVY,
        transform: `translateY(${panelY}%)`, display: "flex", flexDirection: "column",
        padding: `${(portrait ? 11 : 8) * u}px ${4.8 * u}px ${(portrait ? 8 : 5) * u}px` }}>
        {/* 4. Short red bar */}
        <div style={{ position: "absolute", top: 0, left: 0, width: "25.6%", height: 0.9 * u, background: RED,
          transformOrigin: "left center", transform: `scaleX(${redBar})` }} />

        {/* 5. Price box straddling the panel edge */}
        {price ? (
          <div style={{ position: "absolute", top: 0, right: 4.8 * u, transform: "translateY(-55%)" }}>
            <div style={{ background: WHITE, borderRadius: 1.4 * u, padding: `${1.6 * u}px ${3 * u}px`,
              fontFamily: FONTS.body, fontWeight: 700, fontSize: priceSize, lineHeight: 1, color: NAVY,
              whiteSpace: "nowrap", opacity: Math.min(1, Math.max(0, sPrice * 1.5)),
              transform: `translateY(${(1 - sPrice) * -4 * u}px) scale(${0.6 + 0.4 * sPrice})`,
              transformOrigin: "center bottom" }}>
              {price}
            </div>
          </div>
        ) : null}

        {portrait ? (
          <>
            {textBlock}
            <div style={{ marginTop: 3 * u, display: "flex", alignItems: "center", justifyContent: "space-between",
              gap: 2 * u }}>
              {agentBlock}
              {logoBlock}
            </div>
            {footerBlock}
          </>
        ) : (
          <>
            <div style={{ display: "flex", alignItems: "flex-end", justifyContent: "space-between", gap: 4 * u }}>
              <div style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column" }}>{textBlock}</div>
              <div style={{ display: "flex", flexDirection: format === "half" ? "column" : "row",
                alignItems: format === "half" ? "flex-end" : "center", gap: 2.5 * u, flexShrink: 0 }}>
                {agentBlock}
                {logoBlock}
              </div>
            </div>
            {footerBlock}
          </>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default ImovelFichaRevelacao;
